test('issueInvoice assigns number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
});

test('issueInvoice uses next number when others exist', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r2 = issueInvoice(r.value, ['INV-2026-0001', 'INV-2026-0002']);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice does not mutate original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const original = r.value;
  issueInvoice(original, []);
  assert.equal(original.status, 'draft');
  assert.equal(original.number, undefined);
});

