test('invoiceTotals calculates discount correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 9500; // 95000 cents
  const discount = Math.round((subtotal * 10) / 100); // 9500 cents
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const line1Total = 10 * 9500;
  const line2Total = 5 * 8500;
  const subtotal = line1Total + line2Total;
  const discount1 = Math.round((line1Total * 10) / 100);
  const discount2 = Math.round((line2Total * 20) / 100);
  const totalDiscount = discount1 + discount2;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, totalDiscount);
  assert.equal(totals.total, subtotal - totalDiscount);
});

test('invoiceTotals clamps total at zero', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals handles decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 10 * 9500;
  const discount = Math.round((subtotal * 12.5) / 100);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount);
});

